use std::collections::BTreeMap;use artifactum_core::{provider_error,AcquireContext,AcquisitionPlan,ArtifactPath,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,ResolvedFile,ResolvedRevision,Resolution};use artifactum_provider_api::{apply_headers,bearer_headers,client,json,plan,profile_value};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct OsfProvider;#[async_trait]impl ArtifactProvider for OsfProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"osf".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["osf".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<Resolution>{if r.revision.is_some(){return Err(provider_error("osf","explicit file-version resolution is not yet supported; use the immutable OSF file id/current version"));}let id=r.reference.locator();let base=profile_value(c,"api_base").unwrap_or("https://api.osf.io/v2").trim_end_matches('/');let headers=bearer_headers(c.profile.as_ref(),"token_env","OSF_TOKEN");let v=json("osf",apply_headers(client()?.get(format!("{base}/files/{id}/")),&headers).send().await.map_err(|e|provider_error("osf",e))?).await?;let data=v.get("data").ok_or_else(||provider_error("osf","response missing data"))?;let a=data.get("attributes").cloned().unwrap_or_default();let name=a.get("name").and_then(|v|v.as_str()).unwrap_or(id);let url=data.pointer("/links/download").and_then(|v|v.as_str()).ok_or_else(||provider_error("osf","file missing download link"))?;let file=ResolvedFile{path:ArtifactPath::new(name)?,size:a.get("size").and_then(|v|v.as_u64()),digests:Default::default(),media_type:a.get("content_type").and_then(|v|v.as_str()).map(str::to_owned),source:serde_json::json!({"url":url})};let rev=a.get("date_modified").and_then(|v|v.as_str()).unwrap_or(id).to_owned();Ok(Resolution{provider:"osf".into(),canonical_ref:format!("osf:{id}"),revision:Some(ResolvedRevision{id:rev,requested:None}),files:vec![file],provider_state:serde_json::Value::Null,metadata:BTreeMap::new()})}async fn prepare_acquisition(&self,f:&ResolvedFile,c:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{let url=f.source.get("url").and_then(|v|v.as_str()).ok_or_else(||provider_error("osf","missing download URL"))?;let headers=bearer_headers(c.profile.as_ref(),"token_env","OSF_TOKEN");Ok(plan(url,headers))}}
pub fn provider()->OsfProvider{OsfProvider}
